/*
  # Update "Other Games" Icon with Styled Background

  1. Changes
    - Updates the image_url for "Other Games" to use a custom SVG with gradient background
    - The SVG features a dark blue gradient background with glowing shapes icon
    - Matches the visual style of other game cover images

  2. Design
    - Dark gradient background (#1a1a2e to #0f3460)
    - Cyan accent color (#00d9ff) for the shapes icon
    - Subtle glow effects and decorative elements
    - 400x400 canvas for high resolution display
*/

UPDATE games
SET image_url = 'data:image/svg+xml;base64,'
WHERE name = 'Other Games';